from pathlib import Path
import shutil,time,re
p=Path('/opt/bringness-delivery-sandbox/apps/web/public/bestellen')
b=Path('/opt/bringness-design-backups')/('mobile-icons-'+str(int(time.time())))
shutil.copytree(p,b)
h=p/'index.html'
s=h.read_text()
marker='<section aria-labelledby="results-heading">'
assert marker in s
items=[('🍔','Essen','Restaurants entdecken'),('🥬','Lebensmittel','Demnächst'),('📰','Kiosk & Presse','Demnächst'),('💐','Blumen','Demnächst'),('👕','Mode','Demnächst')]
icons='<section class="shop-categories" aria-labelledby="categoryHeading"><h2 id="categoryHeading">Was darf’s heute sein?</h2><p>Entdecke Bringness in deiner Nähe.</p><div class="category-icons">'
for emoji,label,detail in items:
    tag='a' if label=='Essen' else 'div'
    attr=' href="#results-heading"' if tag=='a' else ''
    icons+=f'<{tag} class="category-choice{" soon" if tag=="div" else ""}"{attr}><span class="category-figure" aria-hidden="true">{emoji}<i>☺</i></span><strong>{label.replace("&","&amp;")}</strong><small>{detail}</small></{tag}>'
icons+='</div></section>'
if 'class="shop-categories"' not in s:s=s.replace(marker,icons+marker)
s=re.sub(r'style\.css(?:\?[^"]*)?"','style.css?v=mobile-icons-20261127"',s)
css="\n/* Bringness mobile-icons-20261127 */\n:root{color-scheme:dark}*{box-sizing:border-box}body,.search-page,main>section:not(.intro),.search-page main>section{background:#242a2e;color:#f3ede4}\nheader,.search-page header{background:#1c2226;color:#f3ede4}\n#search,.search-page #locationEditor #search,#restaurantControls,article,#demoBasket,.restaurant-card{background:#343b40;color:#f3ede4;border-color:#788087}\ninput,select,.search-row input,#addressSearch,#restaurantToolbar input,#restaurantToolbar select{background:#242a2e;color:#fff7ed;border:1px solid #8a9298;min-height:48px;font-size:16px}\ninput::placeholder{color:#c4c6c8}#addressSource,#addressSource a,#addressMessage,#useLocation,.search-page #status,#restaurantControls button{color:#e1d3c2}\n#addressSuggestions{background:#343b40;color:#fff7ed;border-color:#8a9298}#addressSuggestions button{background:#343b40;color:#fff7ed;text-align:left;min-height:48px}#addressSuggestions button:hover,#addressSuggestions button:focus{background:#4b5359}\nbutton,a,input,select{touch-action:manipulation}button{min-height:44px}:focus-visible{outline:3px solid #ffb87e;outline-offset:4px}\n.search-page #restaurantHighlights{display:none!important}.shop-categories{padding:28px clamp(16px,6vw,96px)!important}.shop-categories h2{margin:0 0 6px;font-size:clamp(1.4rem,3vw,2rem)}.shop-categories>p{color:#c7c4bf;margin:0 0 22px}\n.category-icons{display:flex;gap:clamp(14px,4vw,54px);flex-wrap:wrap}.category-choice{display:grid;justify-items:center;align-content:start;gap:8px;min-width:110px;color:#fff0e1;text-decoration:none;text-align:center}.category-choice small{font-size:.78rem;color:#c9c2b8}.category-figure{position:relative;display:grid;place-items:center;font-size:3rem;width:88px;height:88px;border-radius:50%;background:#f6bc80;box-shadow:0 5px 0 #ad683d;transform:rotate(-7deg)}.category-choice:nth-child(2) .category-figure{background:#c7d399;transform:rotate(6deg)}.category-choice:nth-child(3) .category-figure{background:#b9cee0;transform:rotate(-5deg)}.category-choice:nth-child(4) .category-figure{background:#d9b9c7;transform:rotate(5deg)}.category-choice:nth-child(5) .category-figure{background:#c8b9d9}.category-figure i{position:absolute;bottom:-8px;right:-3px;font-style:normal;font-size:1.5rem;background:#ffdcac;color:#422f22;border-radius:50%;width:30px;height:30px;line-height:28px}.category-choice:hover .category-figure{transform:rotate(0)}.soon small{border:1px solid #7e837f;border-radius:20px;padding:2px 8px}\n.search-page #results-heading{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%)}.search-page #locationSummary{background:#394147;color:#ffe0bb}.ordering-modes{background:#343b40}.ordering-modes a{color:#eee0cc}.ordering-modes a[aria-current=page]{background:#f6bc80;color:#322318}\n#restaurantToolbar input,#restaurantToolbar select{width:100%;max-width:100%}.intro #search{width:min(100%,34rem)}.search-row,.search-row label{min-width:0}.search-row input{max-width:100%}\n@media(max-width:650px){header,.search-page header{gap:10px;padding:14px 16px;flex-wrap:wrap}nav{gap:12px;font-size:.85rem}header a{min-height:44px;display:inline-flex;align-items:center}.intro{min-height:auto;padding:36px 16px 160px}h1{font-size:clamp(2.6rem,12vw,4.5rem);max-width:12ch}.intro-content{min-width:0;width:100%}#search{padding:16px;width:100%;margin-top:20px}.search-row{display:grid;grid-template-columns:minmax(0,1fr);width:100%}.search-row input,.search-row button{width:100%}#search fieldset label{min-height:44px;display:inline-flex;align-items:center;gap:7px}.shop-categories{padding:24px 16px!important}.category-icons{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 10px}.category-choice{min-width:0;font-size:.85rem}.category-choice small{font-size:.7rem}.category-figure{width:72px;height:72px;font-size:2.4rem}.category-choice strong{overflow-wrap:anywhere}.search-page main>section{padding-inline:16px}.search-page #restaurantToolbar:not([hidden]){display:grid;grid-template-columns:minmax(0,1fr);gap:12px}.search-page #restaurants{grid-auto-columns:100%;min-width:0}#orderingLocation{gap:10px}.search-page #locationEditor #search{position:fixed;left:12px;right:12px;top:100px;width:auto;max-width:none;max-height:70svh;overflow:auto}.campaign{max-width:calc(100% - 32px)}#demoBasket{padding:16px}#basketItems{padding-left:20px}article{min-width:0;overflow-wrap:anywhere}}\n@media(max-width:350px){.category-icons{grid-template-columns:repeat(2,minmax(0,1fr))}nav{gap:8px}}@media(prefers-reduced-motion:reduce){.category-figure{transform:none!important}}\n"
f=p/'style.css'
t=f.read_text()
if 'Bringness mobile-icons-20261127' not in t:f.write_text(t+css)
h.write_text(s)
print('DESIGN_PATCH_OK',b)
